#!/usr/bin/env bash
# Turns the former urls listed in dist/redirects.json into permanent redirects on S3.
#
# S3 answers with a 301 to the `x-amz-website-redirect-location` of an object, as long as it is requested
# through the website endpoint of the bucket. The object keeps the page generated by the prerender
# (a `meta refresh` and a canonical to the target) as its body, a fallback for any other endpoint.
#
# `aws s3 sync` uploads these pages again without their metadata, so this script runs after every sync.
#
# Usage: bin/apply-s3-redirects.sh <bucket> [redirects file] [public dir]
set -euo pipefail

BUCKET="${1:?Usage: $0 <bucket> [redirects file] [public dir]}"
REDIRECTS_FILE="${2:-dist/redirects.json}"
PUBLIC_DIR="${3:-dist/public}"
# The urls of the manifest start with the base url, so do the keys of the bucket
BASE_URL="${BASE_URL:-/}"

count=0
while IFS=$'\t' read -r from to; do
  key="${from#/}index.html"
  body="${PUBLIC_DIR}/${from#"$BASE_URL"}index.html"

  aws s3api put-object \
    --bucket "$BUCKET" \
    --key "$key" \
    --body "$body" \
    --content-type "text/html; charset=utf-8" \
    --website-redirect-location "$to" \
    > /dev/null

  echo "301 ${from} -> ${to}"
  count=$((count + 1))
done < <(jq -r '.[] | [.from, .to] | @tsv' "$REDIRECTS_FILE")

echo "${count} redirects applied on s3://${BUCKET}"
